// Ambient types for the virtual modules generated by @jixoai/ui-vite-plugin
// at build/dev time. Named exports only — the module shapes match the
// generating sources exactly.
//
// Consumer wiring (one line in a project d.ts environment file):
//   /// <reference types="@jixoai/ui-vite-plugin/client" />

declare module 'virtual:jixoai-ghostty' {
  export const url: string;
  export const sha256: string;
  export const variant: 'full' | 'small';
  export const buildInfo: string;
}

// The icons feature (jixoai({ icons: { provider | library } })). The CSS
// form is consumed via `@import 'virtual:jixoai-icons';` (no JS types
// needed); the explicit `?dom` form carries the DOM-injection SVG
// strings for slots consumed as inline SVG.
declare module 'virtual:jixoai-icons?dom' {
  import type { IconSlot } from '@jixoai/ui-vite-plugin/icons';
  export const domIcons: Partial<Record<IconSlot, string>>;
  export default domIcons;
}

// The icons LIBRARY face's lazy chunk modules (icon-component-pipeline,
// design §3): `virtual:jixoai-icons/chunk/K` is generated at dev/build
// time by whichever app wires jixoai({ icons: { library } }) — chunk
// bodies are never files. Types-only shape (the artifact's LAZY loaders
// import these dynamically; a plugin-free artifact has zero of them).
declare module 'virtual:jixoai-icons/chunk/*' {
  import type { IconData } from '@jixoai/ui-vite-plugin/icons';
  const icons: Readonly<Record<string, IconData>>;
  export default icons;
}

// The canvas same-source per-page modules (typography-context-and-parts
// design §7): `virtual:jixoai-canvas/<route-rel>/+page` is generated at
// dev/build time by canvasPlugin() — the page's id-keyed
// <ComponentCanvas> children slices. A page imports ONLY its own
// module (the plugin's resolveId rejects cross-page importers by
// name). Named exports only, pure data + one lookup function — no
// default export (the virtual:jixoai-ghostty surface law).
declare module 'virtual:jixoai-canvas/*' {
  /** the page's extraction-keyed canvas ids, in document order */
  export const canvasIds: readonly string[];
  /**
   * the canvas's own children markup (dedented, direct-child canvas
   * protocol snippets stripped, comments kept — byte-honest). Throws a
   * named error listing the page's real ids on a miss.
   */
  export function resolveRawCode(id: string): string;
}
